#include <iostream>
#include <numeric>
#include <ranges>

int main() {
    constexpr int n{4};

    constexpr auto v1 = std::views::iota(1) | std::views::take(n) | std::views::common;
    constexpr auto v2 = std::views::iota(2) | std::views::take(n);
    const int product = std::inner_product(v1.begin(), v1.end(), v2.begin(), 0);
    std::cout << product << '\n';
}
